// WordCraft's tools for agents in Misty, over the page command API every Craft web build puts on
// `window.wordcraft` (storytold/craft-libs `crates/web-api`): the same commands the app's desktop control
// server and its own MCP server run (`docs/control-protocol.md`, `docs/mcp.md`). Misty loads this script into
// the running app and offers these tools as the app's own; it changes nothing about the app.
(function () {
  "use strict";
  var APP = "wordcraft";

  function api() {
    var page = window[APP];
    if (!page || typeof page.request !== "function") throw new Error("WordCraft is still starting. Try again in a moment.");
    return page;
  }

  function object(value) {
    return value && typeof value === "object" && !Array.isArray(value) ? value : {};
  }

  var tools = [
    {
      name: "commands",
      description: "List WordCraft's commands: each one's id, label, where it is in the app, its shortcut, the params it takes and whether it is enabled now. Pass search to narrow the list (such as \"table\" or \"style\"). Run one with execute.",
      inputSchema: {
        type: "object",
        properties: { search: { type: "string", description: "Words to narrow the list by." } },
        additionalProperties: false,
      },
      annotations: { readOnlyHint: true },
    },
    {
      name: "execute",
      description: "Run one of WordCraft's commands in the open document, as its menus and ribbon do: an id from commands (such as text.insert with {\"text\": \"Hello\"}) and its params. Read the document with inspect_document before and after a change.",
      inputSchema: {
        type: "object",
        properties: {
          command: { type: "string", description: "The command's id, from commands." },
          params: { type: "object", description: "The command's params, as commands lists them." },
          doc: { type: "number", description: "Which open document, from inspect_ui's documents; the active one when left out." },
        },
        required: ["command"],
        additionalProperties: false,
      },
      annotations: { readOnlyHint: false },
    },
    {
      name: "inspect_document",
      description: "Read the open document: its blocks (text, style, runs, lists and tables), parts, sections, the selection and its pages. Pass text to look for the blocks holding it.",
      inputSchema: {
        type: "object",
        properties: {
          text: { type: "string", description: "Text to find in the document." },
          doc: { type: "number", description: "Which open document; the active one when left out." },
        },
        additionalProperties: false,
      },
      annotations: { readOnlyHint: true },
    },
    {
      name: "inspect_ui",
      description: "Read WordCraft's own state: the open view and dialog, the caret, the window's size, where the pages are on screen, and the open documents with their ids, titles and whether they have unsaved changes.",
      inputSchema: { type: "object", properties: {}, additionalProperties: false },
      annotations: { readOnlyHint: true },
    },
  ];

  function call(name, args) {
    var input = object(args);
    var page = api();
    switch (name) {
      case "commands":
        return page.request("engine.commands", typeof input.search === "string" && input.search ? { search: input.search } : {});
      case "execute": {
        if (typeof input.command !== "string" || !input.command) throw new Error("Name the command to run, from commands.");
        var params = { command: input.command, params: object(input.params) };
        if (typeof input.doc === "number") params.doc = input.doc;
        return page.request("engine.execute", params);
      }
      case "inspect_document": {
        var query = {};
        if (typeof input.text === "string" && input.text) query.text = input.text;
        if (typeof input.doc === "number") query.doc = input.doc;
        return page.request("document.inspect", query);
      }
      case "inspect_ui":
        return page.request("ui.inspect", {});
      default:
        throw new Error("WordCraft has no tool called " + name + ".");
    }
  }

  window.mistyAdapter = { tools: tools, call: call };
})();
